pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n);
    assert_eq!(conds_1.len(), n);
    assert_eq!(conds_2.len(), n);

    // Ensure output has the right length and can be overwritten.
    avgs.resize(n, 0);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // Problem assumption: at least one condition is true.
        debug_assert!(c1 || c2);

        let v1 = vals_1[i];
        let v2 = vals_2[i];

        // Problem assumption: values are < 1000 (so v1 + v2 cannot overflow u64 anyway).
        debug_assert!(v1 < 1000 && v2 < 1000);

        avgs[i] = match (c1, c2) {
            (true, true) => (v1 + v2) / 2,
            (true, false) => v1,
            (false, true) => v2,
            (false, false) => unreachable!("by assumption, at least one condition is true"),
        };
    }
}